  const locked = () => !editing || busy;
  function status(text, kind = '') { const output = $('#outputState'); output.textContent = text; output.className = `ui-status ${kind ? `is-${kind}` : ''}`; }
  function sharedLabel(channels) { return channels.length > 1 ? `SHARED ${channels.map(channel => model.way(channel).name).join('/')}` : 'THIS WAY'; }
  async function run(operation) { if (locked()) return; busy = true; render(); status('APPLYING'); try { await operation(); status('DSP API READY', 'success'); } catch (error) { status(`ERROR · ${error.message}`, 'critical'); await service.refresh().catch(() => {}); } finally { busy = false; render(); } }
  function valueFraction(spec, value) { return spec.logarithmic ? (Math.log(value) - Math.log(spec.min)) / (Math.log(spec.max) - Math.log(spec.min)) : (value - spec.min) / (spec.max - spec.min); }
