    $('#selectedWayTitle').textContent = `${item.name} · RESPONSE`; $('#selectedWayMeta').textContent = `OUT ${item.channel + 1} · post-mixer · ${item.crossover.hpf ? hz(item.crossover.hpf.filter.parameters.freq) : 'no HPF'} → ${item.crossover.lpf ? hz(item.crossover.lpf.filter.parameters.freq) : 'no LPF'}`;
