      rotary('limiter', 'HARD LIMIT', Number(limiter.clip_limit || 0), -60, 0, .1, 'dBFS', value => service.setHardLimiter(item.channel, value), { format: value => `${Number(value).toFixed(1)} dBFS`, meta: 'CLIP LIMIT' }),
      `<article class="output-module"><strong>OUTPUT STATE</strong><button class="ui-button ${gain.mute ? 'is-danger' : ''}" data-mute type="button" ${locked() ? 'disabled' : ''}>${gain.mute ? 'MUTED' : 'ON'}</button><button class="ui-button ${gain.inverted ? 'is-warning' : ''}" data-polarity type="button" ${locked() ? 'disabled' : ''}>${gain.inverted ? 'POLARITY · INVERTED' : 'POLARITY · NORMAL'}</button><span class="module-meta">Gain filter only</span></article>`
